# Circular and escape velocity vs altitude (Earth)
import math
MU = 398600.4418  # km^3/s^2
RE = 6378.0        # km

def v_circ(alt_km):
    return math.sqrt(MU / (RE + alt_km))

for alt in (0, 200, 400, 2000, 35786):
    vc = v_circ(alt)
    print("alt %5d km: circular %5.2f km/s, escape %5.2f km/s" % (alt, vc, math.sqrt(2.0)*vc))
